    clean_company_name: cleanCompanyName,
    company_homepage_name: companyHomepageName,
    parent_company: clean(explicitParent || url.parent_company || url.company_homepage_name || url.clean_company_name || cleanCompanyName),
    hia_batch: clean(input.hia_batch),
    status: 'partial',
    best_url: clean(url.best_url),
    canonical_domain: clean(url.canonical_domain),
    duplicate_of_id: '',
    website_content: clean(scrape.website_content),
    full_name: clean(contact.full_name),
    first_name: clean(contact.first_name),
    role: clean(contact.role),
    email: clean(contact.email),
    linkedin_url: clean(contact.linkedin_url),
    contact_source: clean(contact.contact_source) || 'none',
    contact_confidence: clean(contact.contact_confidence) || 'LOW',
    evidence_gap: 'contact_search_complete',
    last_stage: 'contact_search',
    last_error: ''
  }
};

function hostFromUrl(value){
  const raw=String(value||'').trim();
  if(!raw)return '';
  const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;
  const match=withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1]||'').replace(/^www\./i,'').toLowerCase().trim();
}
const input=$('Normalize Input').first().json || {};
const payload=$json || {};
const results=Array.isArray(payload.results) ? payload.results : (Array.isArray(payload.organic) ? payload.organic : []);
const generic=new Set(['singapore','clinic','clinics','medical','medicine','family','doctor','doctors','care','health','healthcare','centre','center','group','holdings','holding','limited','ltd','pte','private','company','services','service','practice','practices']);
const tokens=String(input.company_name || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(t => t.length >= 3 && !generic.has(t));
const noisyHosts=['zhihu.com','stackoverflow.com','microsoft.com','answers.microsoft.com','wikipedia.org','baidu.com','youtube.com','reddit.com','waze.com','neighbourhoodshop.sg','recordowl.com','asiafirms.com','apabuka.com'];
let relevanceScore=0;
let tokenHits=0;
for(const row of results.slice(0,8)){
  const title=String(row?.title || '').toLowerCase();
  const snippet=String(row?.snippet || row?.content || '').toLowerCase();
  const url=String(row?.url || row?.link || '').toLowerCase();
  const host=hostFromUrl(url);
  const text=[title,snippet,url].join(' ');
  const matched=tokens.some(t => text.includes(t));
  if(matched){ tokenHits += 1; relevanceScore += 2; }
  if(host && !noisyHosts.some(h => host===h || host.endsWith('.'+h))) relevanceScore += 1;
  if(host.endsWith('.sg')) relevanceScore += 1;
}
const useSerper = results.length === 0 || tokenHits === 0 || relevanceScore < 4;
return { json: { ...payload, use_serper_homepage: useSerper, searx_result_count: results.length, searx_relevance_score: relevanceScore, searx_token_hits: tokenHits } };
